  const STAGES=["domains","training","levels","cases"];
  const SUBMISSION_BUCKET="professional-track-submissions";
  const RESOURCE_BUCKET="professional-track-resources";
  let selectedDomain="input";
  let activeDomain="input";
  let selectedModule=0;
  let activeModule=0;
  let selectedLevel=0;
  let remoteReady=false;
  let progressReady=false;
  let statePromise=null;
  let stateLoaded=false;
  let viewVersion=0;
  let adminMode=false;
  let supabase=null;
  let activeCases=[];
  const catalog=new Map();
  const submissions=new Map();

  async function client(){
    for(let i=0;i<30;i++){
      const sb=window.avpSupabase||window.supabaseClient||null;
      if(sb?.rpc)return sb;
      await new Promise(resolve=>setTimeout(resolve,100));
    }
    return null;
  }

  function resourcePath(value){
    const raw=String(value||"").trim();
    if(!raw||/^https?:\/\//i.test(raw)||raw.startsWith("//")||raw.startsWith("/")||raw.includes(".."))return "";
    return raw;
  }

  async function openPrivateResource(path,label){
    const clean=resourcePath(path);
    if(!clean)return alert("Tài nguyên này chưa được Admin đưa vào kho Pro riêng tư.");
    supabase=supabase||await client();
    if(!supabase)return alert("Chưa kết nối được hệ thống.");
    const popup=window.open("","_blank");
    try{
      const {data,error}=await supabase.storage.from(RESOURCE_BUCKET).createSignedUrl(clean,120);
      if(error)throw error;
      if(!data?.signedUrl)throw new Error("Không tạo được liên kết tạm thời.");
      if(popup){popup.opener=null;popup.location.replace(data.signedUrl)}else window.location.href=data.signedUrl;
    }catch(error){
      if(popup)popup.close();
      alert(`Không mở được ${label||"tài nguyên"}: ${String(error?.message||error)}`);
    }
  }

  function caseKey(level,index){
    return `${activeDomain}-${activeModule+1}-${level.id}-${index+1}`;
  }

  function loadRemoteState(force=false){
    if(statePromise)return statePromise;
    if(stateLoaded&&!force)return Promise.resolve();
    statePromise=(async()=>{
      const access=await window.AVPProfessionalGateReady;
      if(!access?.allowed)return;
      adminMode=access.isAdmin===true;
      supabase=await client();
      if(!supabase)return;
      // Catalog and progress are independent: an error reading scores must not
      // discard a successfully loaded, published lesson.
      const results=await Promise.allSettled([
        supabase.rpc("professional_track_catalog_v2"),
        supabase.rpc("professional_track_progress_v2")
      ]);
      results.forEach((result,index)=>{
        const response=result.status==="fulfilled"?result.value:null;
        const error=result.status==="rejected"?result.reason:response?.error;
        const ok=!error&&Array.isArray(response?.data);
        if(index===0)remoteReady=ok;else progressReady=ok;
        const map=index===0?catalog:submissions;
        map.clear();
        if(ok)response.data.forEach(row=>map.set(String(row.case_key),row));
        else console.warn(`[Professional Track ${index===0?"catalog":"progress"}]`,error||"invalid_response");
      });
    })().catch(error=>{
      remoteReady=false;progressReady=false;
      console.warn("[Professional Track]",error);
    }).finally(()=>{
      stateLoaded=true;statePromise=null;
      refreshLevelState();
    });
    return statePromise;
  }

  function levelUnlocked(index){
    if(adminMode)return true;
    if(index===0)return true;
    if(progressReady){
      const previous=LEVELS[index-1];
      const scores=previous.caseTemplates.map((_,caseIndex)=>submissions.get(caseKey(previous,caseIndex)))
        .filter(row=>row?.status==="graded")
        .map(row=>Number(row.score)||0);
      return scores.length===previous.caseTemplates.length&&scores.every(score=>score>=7)&&scores.reduce((sum,score)=>sum+score,0)>=25;
    }
    return false;
  }

  function levelStats(level){
    const rows=level.caseTemplates.map((_,caseIndex)=>submissions.get(caseKey(level,caseIndex))).filter(Boolean);
    const graded=rows.filter(row=>row.status==="graded");
    const pending=rows.filter(row=>row.status==="pending").length;
    const revision=rows.filter(row=>row.status==="revision").length;
    const score=graded.reduce((sum,row)=>sum+(Number(row.score)||0),0);
    return {submitted:rows.length,graded:graded.length,pending,revision,score,complete:graded.length===3&&graded.every(row=>(Number(row.score)||0)>=7)&&score>=25};
  }

  function renderModuleProgress(){
    const title=$("proModuleProgressTitle"),grid=$("proModuleProgressGrid");
    if(!title||!grid)return;
    title.textContent=DATA[activeDomain]?.items?.[activeModule]?.title||"Nội dung tập luyện";
    if(!progressReady){
      grid.innerHTML='<p class="pro-module-progress-empty">Chưa đồng bộ được tiến độ. Bài đã phát hành vẫn có thể mở ở cấp được phép; bấm Cập nhật để tải lại điểm.</p>';
      return;
    }
    grid.innerHTML=LEVELS.map((level,index)=>{
      const stat=levelStats(level),unlocked=levelUnlocked(index);
      const detail=stat.complete?"Đã hoàn thành":stat.revision?`${stat.revision} bài cần nộp lại`:stat.pending?`${stat.pending} bài đang xử lý / cần kiểm tra`:`${stat.graded}/3 Case đã đạt`;
      return `<article class="${stat.complete?"complete":unlocked?"current":"locked"}"><div><span>${esc(level.code)}</span><strong>${esc(level.title)}</strong></div><b>${stat.score}/30</b><p>${esc(detail)}</p><i><span style="width:${Math.min(100,Math.round(stat.graded/3*100))}%"></span></i></article>`;
    }).join("");
  }

  function scrollStage(stage){
    const top=Math.max(0,(stage?.getBoundingClientRect().top||0)+window.scrollY-92);
    window.scrollTo({top,behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});
  }

  function showStage(name,shouldScroll=true){
    viewVersion++;
    document.querySelectorAll("[data-pro-stage]").forEach(stage=>{
      stage.hidden=stage.dataset.proStage!==name;
      stage.classList.toggle("is-current",stage.dataset.proStage===name);
    });
    const index=STAGES.indexOf(name);
    document.querySelectorAll("[data-path-step]").forEach((step,i)=>{
      step.classList.toggle("active",i===index);
      step.classList.toggle("done",i<index);
    });
    const titles={
      domains:["Chọn lĩnh vực bạn muốn luyện","Nội dung, Level và Case chỉ xuất hiện sau khi bạn chủ động chọn tầng trước đó."],
      training:[DATA[activeDomain]?.title||"Nội dung tập luyện","Chọn đúng nội dung chuyên môn bạn muốn phát triển."],
      levels:[DATA[activeDomain]?.items?.[activeModule]?.title||"Chọn Level","Đi từ nền tảng ứng dụng đến Case thực tế theo từng cấp độ."],
      cases:[LEVELS[selectedLevel]?.title||"Chọn Case","Mỗi Case có brief, đầu ra và tiêu chí chấm rõ ràng."]
    };
    $("proFlowTitle").textContent=titles[name][0];
    $("proFlowSubtitle").textContent=titles[name][1];
    if(shouldScroll)scrollStage(document.querySelector(`[data-pro-stage="${name}"]`));
  }

  function trainingCard(item,i){
    return `<article class="pro-card pro-training-card" data-roll-card data-id="${esc(activeDomain)}-${i}" data-module-index="${i}"><b>MODULE ${String(i+1).padStart(2,"0")}</b><h3>${esc(item.title)}</h3><p>${esc(item.focus)}</p><span>Chọn nội dung →</span></article>`;
  }

  function lockChip(level,index){
    const stat=levelStats(level);
    if(stat.complete)return '<span class="pro-level-status ready">✓ Hoàn thành 3/3</span>';
    if(levelUnlocked(index))return `<span class="pro-level-status ready">${stat.graded?`${stat.graded}/3 Case đã đạt`:index===0?"Mở sẵn":"Đã mở"}</span>`;
    return `<span class="pro-level-status locked">🔒 ${esc(level.requirement)}</span>`;
  }

  function levelCard(level,index){
    const unlocked=levelUnlocked(index);
    const stat=levelStats(level);
    return `<article class="pro-card pro-level-card${unlocked?"":" locked"}" data-roll-card data-id="${esc(level.id)}" data-level-index="${index}"><b>${esc(level.code)}</b><h3>${esc(level.title)}</h3><p>${esc(level.description)}</p>${lockChip(level,index)}<span>${unlocked?(stat.submitted?`Tiếp tục · ${stat.submitted}/3 đã nộp →`:"Xem 3 Case →"):esc(level.requirement)}</span></article>`;
  }

  function refreshLevelState(){
    document.querySelectorAll('#proLevelRollMount [data-level-index]').forEach(card=>{
      const index=Number(card.dataset.levelIndex),level=LEVELS[index];
      const unlocked=levelUnlocked(index),stat=levelStats(level);
      card.classList.toggle("locked",!unlocked);
      const chip=card.querySelector('.pro-level-status');
      if(chip)chip.outerHTML=lockChip(level,index);
      card.lastElementChild.textContent=unlocked?(stat.submitted?`Tiếp tục · ${stat.submitted}/3 đã nộp →`:"Xem 3 Case →"):level.requirement;
    });
    renderModuleProgress();
  }

  function bindRollChoice(root,onChoose){
    root.addEventListener("click",e=>{
      const card=e.target.closest("[data-roll-card]");
      if(!card||!card.classList.contains("active"))return;
      onChoose(card);
    });
    root.addEventListener("keydown",e=>{
      if(e.key!=="Enter"&&e.key!==" ")return;
      if(e.target.closest('button,a,input,label,textarea,select'))return;
      const card=root.querySelector("[data-roll-card].active");
      if(!card)return;
      e.preventDefault();onChoose(card);
    });
  }

  function disposeRoll(mount){
    const roll=mount?.querySelector?.("[data-roll]");
    try{roll?._avpRoll?.resizeObserver?.disconnect()}catch(_){}
  }

  function openDomain(id){
    activeDomain=DATA[id]?id:"input";
    selectedModule=0;
    const domain=DATA[activeDomain];
    $("proTrainingDomainLabel").textContent=`${domain.title.toUpperCase()} · 5 NỘI DUNG`;
    $("proTrainingTitle").textContent="Chọn nội dung tập luyện";
    const mount=$("proTrainingRollMount");
    disposeRoll(mount);
    mount.innerHTML=`<div class="pro-roll pro-training-roll" data-roll="training" data-start="0" tabindex="0"><div class="pro-roll-stage">${domain.items.map(trainingCard).join("")}</div><div class="pro-roll-dots" data-roll-dots></div></div>`;
    const root=mount.querySelector("[data-roll]");
    root.addEventListener("avp:professional-roll-change",e=>{selectedModule=e.detail.index});
    window.AVPProfessionalRoll?.init(root);
    bindRollChoice(root,card=>openModule(Number(card.dataset.moduleIndex)||0));
    showStage("training");
  }

  function openModule(index,shouldScroll=true){
    activeModule=Math.max(0,Math.min(index,DATA[activeDomain].items.length-1));
    selectedLevel=0;
    const module=DATA[activeDomain].items[activeModule];
    $("proLevelModuleTitle").textContent=module.title;
    const mount=$("proLevelRollMount");
    disposeRoll(mount);
    mount.innerHTML=`<div class="pro-roll pro-level-roll" data-roll="levels" data-start="0" tabindex="0"><div class="pro-roll-stage">${LEVELS.map(levelCard).join("")}</div><div class="pro-roll-dots" data-roll-dots></div></div>`;
    const root=mount.querySelector("[data-roll]");
    root.addEventListener("avp:professional-roll-change",e=>{selectedLevel=e.detail.index});
    window.AVPProfessionalRoll?.init(root);
    bindRollChoice(root,card=>openLevel(Number(card.dataset.levelIndex)||0));
    const notice=$("proFlowNotice");notice.hidden=true;notice.textContent="";
    renderModuleProgress();
    showStage("levels",shouldScroll);
  }

  function buildCases(level,module){
    return level.caseTemplates.map((template,index)=>{
      const id=caseKey(level,index);
      const row=catalog.get(id)||{};
      return {
        ...template,
        id,
        title:row.title||template.title,
        goal:row.goal||template.goal,
        tasks:Array.isArray(row.tasks)&&row.tasks.length?row.tasks:template.tasks,
        module:module.title,
        skills:row.skills||module.skills,
        output:row.expected_output||module.output,
        duration:row.duration||level.duration,
        score:Number(row.max_score)||10,
        sourcePath:resourcePath(row.source_url),
        guidePath:resourcePath(row.guide_url),
        published:row.published===true,
        adminDraftTest:adminMode&&catalog.has(id)&&row.published!==true,
        submissionEnabled:row.submission_enabled!==false&&(row.published===true||(adminMode&&catalog.has(id))),
        submission:submissions.get(id)||null
      };
    });
  }

  function isAutoFeedback(value){return String(value||"").startsWith("[AUTO PRO ")}
  function isAutoReview(value){return String(value||"").startsWith("[AUTO REVIEW]")}

  function caseCard(item,index){
    const submission=item.submission;
    const state=submission?.status==="graded"
      ?`${isAutoFeedback(submission.feedback)?"Auto-Grader":"Đã chấm"} ${Number(submission.score)||0}/${item.score}`
      :submission?.status==="pending"
        ?(isAutoReview(submission.feedback)?"Cần Admin kiểm tra":"Đang chấm tự động")
        :submission?.status==="revision"?"Cần nộp lại":item.published?"Đã phát hành":item.adminDraftTest?"Draft · Admin test":"Case mẫu";
    return `<button class="pro-case-card" type="button" data-case-index="${index}"><span>CASE ${String(index+1).padStart(2,"0")}</span><em class="pro-case-state ${esc(item.submission?.status||"")}">${esc(state)}</em><h3>${esc(item.title)}</h3><p>${esc(item.goal)}</p><div><small>${esc(item.duration)}</small><b>${item.score} điểm</b></div><strong>Xem brief →</strong></button>`;
  }

  function renderCases(levelIndex){
    selectedLevel=levelIndex;
    const level=LEVELS[levelIndex];
    const module=DATA[activeDomain].items[activeModule];
    const cases=buildCases(level,module);
    activeCases=cases;
    $("proCaseLevelLabel").textContent=`${DATA[activeDomain].title.toUpperCase()} · ${level.code}`;
    $("proCaseLevelTitle").textContent=module.title;
    const grid=$("proCaseGrid");
    grid.innerHTML=cases.map(caseCard).join("");
    grid.hidden=false;
    const brief=$("proCaseBrief");brief.hidden=true;brief.innerHTML="";
    grid.querySelectorAll("[data-case-index]").forEach(button=>{
      button.addEventListener("click",()=>openCase(cases[Number(button.dataset.caseIndex)]));
    });
  }

  async function openLevel(index){
    selectedLevel=index;
    const grid=$("proCaseGrid"),brief=$("proCaseBrief");
    grid.hidden=false;brief.hidden=true;
    grid.innerHTML='<p class="pro-module-progress-empty" role="status">Đang tải bài đã phát hành…</p>';
    showStage("cases");
    const version=viewVersion;
    await loadRemoteState();
    if(version!==viewVersion)return;
    if(!levelUnlocked(index)){
      const notice=$("proFlowNotice");
      notice.textContent=progressReady?`${LEVELS[index].title} đang khóa. ${LEVELS[index].requirement} để mở cấp này.`:"Chưa tải được tiến độ để xác nhận cấp này. Bấm Cập nhật rồi thử lại.";
      notice.hidden=false;
      showStage("levels");
      return;
    }
    if(!remoteReady){
      grid.innerHTML='<div class="pro-module-progress-empty" role="alert"><p>Chưa tải được danh sách bài Pro. Bài đã đăng chưa bị xóa; hãy thử tải lại.</p><button class="pro-flow-back" type="button" data-pro-retry>Thử tải lại bài</button></div>';
      grid.querySelector('[data-pro-retry]').addEventListener('click',()=>{
        stateLoaded=false;openLevel(index);
      });
      return;
    }
    renderCases(index);
  }

  function openCase(item){
    const grid=$("proCaseGrid");grid.hidden=true;
    const brief=$("proCaseBrief");
    const submission=item.submission;
    const status=submission?.status==="graded"
      ?`${isAutoFeedback(submission.feedback)?"Auto-Grader":"Đã chấm"}: ${Number(submission.score)||0}/${item.score} điểm${submission.feedback?` · ${esc(submission.feedback)}`:""}`
      :submission?.status==="pending"
        ?(isAutoReview(submission.feedback)?`Auto-Grader chưa đủ điều kiện kết luận. Bài đã chuyển sang hàng chờ Admin.${submission.feedback?` ${esc(submission.feedback)}`:""}`:"Bài đã nộp và đang được chấm tự động.")
        :submission?.status==="revision"?`Admin yêu cầu nộp lại${submission.feedback?`: ${esc(submission.feedback)}`:"."}`:"";
    const actions=(item.published||item.adminDraftTest)?`${item.adminDraftTest?'<p class="pro-case-next"><strong>ADMIN TEST:</strong> Case đang Draft. Kết quả chỉ dùng kiểm thử trước khi phát hành.</p>':""}<div class="pro-case-submit-box">${item.submissionEnabled?'<label class="pro-case-note"><span>Ghi chú cho Admin</span><textarea data-pro-case-note rows="2" maxlength="1200" placeholder="Nêu phần cần lưu ý hoặc cách bạn xử lý Case này"></textarea></label>':""}<div class="pro-case-actions">${item.sourcePath?`<button type="button" data-pro-resource="source">↓ Tải file thực hành</button>`:""}${item.guidePath?`<button type="button" class="secondary" data-pro-resource="guide">Xem hướng dẫn</button>`:""}${item.submissionEnabled?`<label class="pro-case-upload"><input type="file" data-pro-case-file accept=".xlsx,.xls,.xlsm,.csv,.zip"><span>${submission?.status==="pending"?"Thay file đã nộp":"Chọn file bài làm"}</span></label><button type="button" data-pro-case-submit>Nộp bài</button>`:""}</div></div>`:`<p class="pro-case-next">Case đang ở chế độ xem trước. Admin chưa phát hành file nguồn và cổng nộp bài.</p>`;
    brief.innerHTML=`<button type="button" class="pro-case-list-back" data-case-list>← Danh sách 3 Case</button><div class="pro-case-brief-head"><div><span>${esc(item.id.toUpperCase())}</span><h2>${esc(item.title)}</h2><p>${esc(item.goal)}</p></div><div><small>Thời lượng dự kiến</small><strong>${esc(item.duration)}</strong><small>Điểm tối đa</small><strong>${item.score}/10</strong></div></div><div class="pro-case-brief-body"><section><h3>Yêu cầu thực hiện</h3><ol>${item.tasks.map(task=>`<li>${esc(task)}</li>`).join("")}</ol></section><section><h3>Năng lực đánh giá</h3><p>${esc(item.skills)}</p><h3>Kết quả phải bàn giao</h3><p>${esc(item.output)}</p></section></div><div class="pro-case-rubric"><span><b>AUTO</b> Cấu trúc, công thức và tính toàn vẹn</span><span><b>AUTO</b> Kết quả, số liệu và đối soát theo đáp án ẩn</span><span><b>REVIEW</b> Chỉ ngoại lệ máy chưa thể kết luận mới chuyển Admin</span></div>${status?`<p class="pro-case-submission-state ${esc(submission?.status||"")}">${status}</p>`:""}${actions}`;
    brief.hidden=false;
    brief.querySelector("[data-case-list]").addEventListener("click",()=>{brief.hidden=true;grid.hidden=false;scrollStage($("proCaseSection"))});
    brief.querySelector("[data-pro-case-file]")?.addEventListener("change",event=>{
      const name=event.target.files?.[0]?.name||"Chọn file bài làm";
      const label=event.target.closest("label")?.querySelector("span");if(label)label.textContent=name;
    });
    brief.querySelector('[data-pro-resource="source"]')?.addEventListener("click",()=>openPrivateResource(item.sourcePath,"file thực hành"));
    brief.querySelector('[data-pro-resource="guide"]')?.addEventListener("click",()=>openPrivateResource(item.guidePath,"hướng dẫn"));
    brief.querySelector("[data-pro-case-submit]")?.addEventListener("click",()=>submitCase(item,brief));
    scrollStage($("proCaseSection"));
  }

  async function submitCase(item,brief){
    if(!supabase)return alert("Chưa kết nối được hệ thống. Hãy tải lại trang.");
    const input=brief.querySelector("[data-pro-case-file]");
    const file=input?.files?.[0];
    if(!file)return alert("Hãy chọn file bài làm trước khi nộp.");
    if(file.size>15*1024*1024)return alert("File bài làm không được vượt quá 15 MB.");
    const ext=(file.name.split(".").pop()||"").toLowerCase();
    if(!["xlsx","xls","xlsm","csv","zip"].includes(ext))return alert("Chỉ nhận XLSX, XLS, XLSM, CSV hoặc ZIP.");
    const {data:{user}}=await supabase.auth.getUser();
    if(!user)return alert("Bạn cần đăng nhập lại trước khi nộp bài.");
    const button=brief.querySelector("[data-pro-case-submit]");
    button.disabled=true;button.textContent="Đang nộp…";
    const cleanName=file.name.normalize("NFKD").replace(/[^a-zA-Z0-9._-]+/g,"-").slice(-90)||`baitap.${ext}`;
    const path=`${user.id}/${item.id}/${Date.now()}-${cleanName}`;
    const previousPath=item.submission?.file_path||"";
    const note=String(brief.querySelector("[data-pro-case-note]")?.value||"").trim();
    try{
      const upload=await supabase.storage.from(SUBMISSION_BUCKET).upload(path,file,{upsert:false,contentType:file.type||undefined});
      if(upload.error)throw upload.error;
      const saved=await supabase.rpc("professional_track_submit_case_v2",{p_case_key:item.id,p_file_path:path,p_original_name:file.name,p_note:note||null});
      if(saved.error){try{await supabase.storage.from(SUBMISSION_BUCKET).remove([path])}catch(_){};throw saved.error}
      if(previousPath&&previousPath!==path){try{await supabase.storage.from(SUBMISSION_BUCKET).remove([previousPath])}catch(_){}}

      button.textContent="Đang chấm tự động…";
      let autoResult=null;
      try{
        const submissionId=Array.isArray(saved.data)?saved.data[0]:saved.data;
        if(submissionId&&supabase.functions?.invoke){
          const grading=await supabase.functions.invoke("professional-grader",{body:{submission_id:String(submissionId),case_key:item.id}});
          if(grading.error)throw grading.error;
          autoResult=grading.data||null;
        }
      }catch(error){
        console.warn("[Professional Auto-Grader]",error);
      }

      await loadRemoteState(true);
      const refreshed=buildCases(LEVELS[selectedLevel],DATA[activeDomain].items[activeModule]);
      activeCases=refreshed;
      renderCases(selectedLevel);
      openCase(refreshed.find(row=>row.id===item.id)||item);
      if(autoResult?.status==="review_required")console.info("[Professional Auto-Grader] Bài cần Admin kiểm tra:",autoResult.reason||"");
    }catch(error){
      alert("Chưa nộp được bài: "+String(error?.message||error));
    }finally{
      if(button.isConnected){button.disabled=false;button.textContent="Nộp bài"}
    }
  }

  async function boot(){
    const domains=document.querySelector('[data-roll="domains"]');if(!domains)return;
    selectedDomain=domains.querySelector('[data-roll-card].active')?.dataset.id||"input";
    domains.addEventListener("avp:professional-roll-change",e=>{selectedDomain=e.detail.id||"input"});
    bindRollChoice(domains,card=>openDomain(card.dataset.id||selectedDomain));

    document.querySelectorAll("[data-pro-back]").forEach(button=>{
      button.addEventListener("click",()=>showStage(button.dataset.proBack));
    });
    $("proProgressRefresh")?.addEventListener("click",async event=>{
      const button=event.currentTarget;button.disabled=true;button.textContent="Đang cập nhật…";
      await loadRemoteState(true);
      button.disabled=false;button.textContent="↻ Cập nhật";
    });
    showStage("domains",false);
    loadRemoteState();
  }

  window.AVPProfessionalTrackData={domains:DATA,levels:LEVELS};
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",()=>boot(),{once:true});else boot();
})();
